verus! {
    /// Given a vector of non-empty character vectors `l`, returns a new vector `r`
    /// such that:
    ///  1. r.len() == l.len()
    ///  2. for all i, r[i] is the last character of l[i].
    ///
    /// We require that each inner vector is non-empty.
    fn extract_rear_chars(l: &Vec<Vec<char>>) -> Vec<char> {
        // Precondition: each inner vector is non-empty
        requires(forall |i: usize| i < l.len() ==> l[i].len() > 0);

        // Postcondition: resulting vector has same length, and r[i] ==
        // last element of l[i]
        ensures(|r: Vec<char>| 
            r.len() == l.len() &&
            forall(|i: usize| i < l.len() ==> r[i] == l[i][l[i].len() - 1])
        );

        let n: usize = l.len();
        let mut res: Vec<char> = Vec::with_capacity(n);
        let mut i: usize = 0;

        // Loop over each index i, maintaining that:
        // 1) i <= n
        // 2) res.len() == i
        // 3) for all j < i, res[j] is the last element of l[j]
        while i < n
            invariant(i <= n);
            invariant(res.len() == i);
            invariant(forall(|j: usize| j < i ==> res[j] == l[j][l[j].len() - 1]));
            decreases(n - i);
        {
            // By precondition and the invariant i < n, l[i] is non-empty
            assert(l[i].len() > 0);
            // Extract the last character
            let c: char = l[i][l[i].len() - 1];
            res.push(c);
            i += 1;
        }

        res
    }
}